from pages7 import SEND
from pages8 import BEFORE,DIRS
C={'pakistan':('Pakistan','For hacking, blackmail or fraud, report to the National Cyber Crime Investigation Agency (NCCIA), which took over from the FIA Cyber Crime Wing.','Urdu','CNIC or passport'),
'philippines':('the Philippines','For scams and hacking, the Cybercrime Investigation and Coordinating Center (CICC) runs the 1326 hotline, and the PNP Anti-Cybercrime Group takes reports.','Filipino','passport, driver’s licence, UMID or PhilSys ID'),
'malaysia':('Malaysia','For online scams where money was lost, call the National Scam Response Centre on 997 as soon as possible. Hacking can also be reported to the police.','Malay','MyKad or passport'),
'nigeria':('Nigeria','For hacking or fraud, report to the Nigeria Police Force National Cybercrime Centre (NPF-NCCC) or your nearest police station.','English','NIN slip, international passport, driver’s licence or voter’s card')}
EQ=('I emailed my appeal letter to Meta. Did it arrive?','Meta does not process account appeals by email. Use the appeal on the notice or in Account Status.')
PAGES=[]
for k,(n,rep,lang,ids) in C.items():
    note=f'<h2 id="local-notes">Notes for {n}</h2><ul><li>Instagram and Facebook work in {lang} and English. You can write the appeal in either.</li><li>IDs that can work when the name matches the profile: {ids}.</li><li>{rep}</li><li>Turn off any VPN and use your usual SIM and phone.</li></ul>'
    rel=DIRS+', '+(L(f'facebook-account-disabled-{k}-what-to-do','Facebook disabled in '+n)+', ' if k=='pakistan' else '')+L(f'meta-appeal-links-{k}','Meta appeal links '+n)+'.'
    N=n.replace('the ','The ',1) if n.startswith('the ') else n
    PAGES.append(mk(f'meta-appeal-links-{k}',f'Meta Appeal Links for {N} (2026): Instagram, Facebook, Ads',f'Meta appeal links {N}',f'Official Meta appeal links for Instagram, Facebook and ad accounts in {n}, with local notes on ID and reporting hacks. Checked November 2026.',f'Meta appeal links for {n}',f'The same official links work in {n}. This page adds local notes.',f'<strong>In {n}, Instagram and Facebook appeals start from the notice at login or from Account Status.</strong> Ad accounts are reviewed in Business Support Home. Meta does not take appeals by email or phone. Use your usual device without a VPN and appeal once. Meta makes the final decision.',[('Instagram','Notice, then Account Status.'),('Facebook','Notice, then Accounts Center.'),('Ads','Business Support Home.')],note,[('ig','Instagram',IG[:4]),('fb','Facebook',FB[:4]),('ads','Ad accounts',ADS[:3])],[BEFORE,SEND],rel,[EQ,(f'Is there a Meta phone number in {N}?','Meta does not offer a phone line for account appeals.')]))
    PAGES.append(mk(f'instagram-hacked-{k}-what-to-do',f'Instagram Hacked in {N}: What to Do (2026)',f'Instagram hacked {N}',f'Your Instagram was hacked and you are in {n}. instagram.com/hacked, the video selfie, and where to report it locally.',f'Instagram hacked in {n}: what to do','Act in the first hour. Here is the order.',f'<strong>If your Instagram was hacked in {n}, start at instagram.com/hacked on your usual phone.</strong> Follow the email, phone or video selfie checks, then secure the account with two-factor authentication. {rep.split(",")[0] if False else ""}Warn followers from another account if scam messages go out. Instagram makes the final decision.',[('Hacked page','instagram.com/hacked'),('Selfie','On your usual phone.'),('Report','Local cybercrime route.')],note,[('ig','Instagram',[IG[1],IG[0],IG[2]])],[BEFORE,SEND],rel,[('The hacker changed my email and number. Can I still recover?','Often, through instagram.com/hacked and a video selfie.'),('Should I pay someone who says they can hack it back?','No. Those offers are scams.')]))
